package com.example.rokidgeminisecretary;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Explicit marks only, bounded encrypted records. Default scope excludes all recording. */
final class NavigationDiagnosticNotes {
 static File file(Context c){return new File(c.getFilesDir(),"navigation-diagnostics.gcm");}
 static String scope(Context c){String s=c.getSharedPreferences("loki_navigation_controls",0).getString("diagnosticScope","off");return s.matches("metrics|location")?s:"off";}
 static void configure(Context c,String scope)throws IOException{if(!scope.matches("off|metrics|location"))throw new IOException("保存範囲が無効です");if(!c.getSharedPreferences("loki_navigation_controls",0).edit().putString("diagnosticScope",scope).commit())throw new IOException("保存範囲を更新できません");}
 static JSONObject safe(JSONObject packet,boolean location,long now)throws Exception{JSONObject out=new JSONObject();if(packet==null)return out.put("available",false);long sample=packet.optLong("locationTime");out.put("available",true).put("locationAgeMs",sample>0&&now>=sample?now-sample:-1);double accuracy=packet.optDouble("accuracy",-1);if(Double.isFinite(accuracy))out.put("accuracyMetres",accuracy);out.put("routeReady",packet.optBoolean("routeReady")).put("refreshing",packet.optBoolean("routeRefreshing")).put("paused",packet.optBoolean("guidancePaused")).put("powerSaving",packet.optString("positionUpdateMode").contains("省電力"));JSONObject walk=packet.optJSONObject("walkProgress");if(walk!=null)out.put("headingConfirmed",walk.optBoolean("headingConfirmed")).put("missedTurn",walk.optBoolean("missed"));String phase=packet.optString("phase");if(phase.matches("FIRST_MILE|BOARDING|TRANSIT_LEG|LAST_MILE"))out.put("phase",phase);if(location){double lat=packet.optDouble("latitude",Double.NaN),lng=packet.optDouble("longitude",Double.NaN);if(Double.isFinite(lat)&&Double.isFinite(lng)&&Math.abs(lat)<=90&&Math.abs(lng)<=180)out.put("latitude",lat).put("longitude",lng);}return out;}
 static synchronized JSONArray read(Context c)throws Exception{AtomicFile a=new AtomicFile(file(c));if(!a.getBaseFile().exists()&&!new File(a.getBaseFile()+".bak").exists())return new JSONArray();byte[] data=a.readFully();if(data.length>256000)throw new IOException("診断記録が大きすぎます");JSONArray rows=new JSONArray(new String(DeviceSecrets.photos().decrypt(data),StandardCharsets.UTF_8)),out=new JSONArray();long now=System.currentTimeMillis();for(int i=0;i<rows.length()&&out.length()<100;i++){JSONObject j=rows.getJSONObject(i);long age=now-j.optLong("at");if(age>=0&&age<86400000)out.put(j);}if(out.length()!=rows.length())store(c,out);return out;}
 static synchronized JSONObject mark(Context c,String reason,JSONObject packet)throws Exception{String scope=scope(c);if(scope.equals("off"))throw new IOException("先に診断の保存範囲を選んでください");if(!reason.matches("late|direction|route|other"))throw new IOException("記録理由が無効です");JSONArray rows=read(c),out=new JSONArray();for(int i=Math.max(0,rows.length()-99);i<rows.length();i++)out.put(rows.getJSONObject(i));JSONObject row=new JSONObject().put("at",System.currentTimeMillis()).put("reason",reason).put("scope",scope).put("metrics",safe(packet,scope.equals("location"),System.currentTimeMillis()));out.put(row);AtomicFile a=new AtomicFile(file(c));FileOutputStream stream=null;try{stream=a.startWrite();stream.write(DeviceSecrets.photos().encrypt(out.toString().getBytes(StandardCharsets.UTF_8)));a.finishWrite(stream);}catch(Exception e){if(stream!=null)a.failWrite(stream);throw e;}return row;}
 private static void store(Context c,JSONArray rows)throws Exception{AtomicFile a=new AtomicFile(file(c));if(rows.length()==0){a.delete();return;}FileOutputStream stream=null;try{stream=a.startWrite();stream.write(DeviceSecrets.photos().encrypt(rows.toString().getBytes(StandardCharsets.UTF_8)));a.finishWrite(stream);}catch(Exception e){if(stream!=null)a.failWrite(stream);throw e;}}
 static synchronized void clear(Context c){new AtomicFile(file(c)).delete();}
 private NavigationDiagnosticNotes(){}
}
